import{_ as e}from"./chunks/robot-settings.DKKw5ez-.js";import{_ as r,o as a,c as o,a2 as s}from"./chunks/framework.eFe5Lsvn.js";const f=JSON.parse('{"title":"Robot configuration","description":"","frontmatter":{},"headers":[],"relativePath":"app/robot.md","filePath":"app/robot.md"}'),d={name:"app/robot.md"};function n(i,t,h,l,c,p){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="robot-configuration" tabindex="-1">Robot configuration <a class="header-anchor" href="#robot-configuration" aria-label="Permalink to &quot;Robot configuration&quot;">​</a></h1><p>Open <strong>Settings</strong> (the sliders icon, top right) and choose <strong>Robot</strong>. Enter the real values: the optimizer uses them as hard physical limits.</p><p><img src="'+e+'" alt="Robot settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Notes</th></tr></thead><tbody><tr><td>Mass, moment of inertia</td><td>Mass with bumpers and battery. Use <strong>Estimate MOI</strong> if you don&#39;t have a CAD value.</td></tr><tr><td>Bumper</td><td>Distances from robot center to each bumper face. Collision checks use this rectangle as it rotates.</td></tr><tr><td>Wheelbase, track width</td><td>Module positions. Order is <strong>FL, FR, BL, BR</strong> (the Tuner X default).</td></tr><tr><td>Wheel radius, μ</td><td>μ ≈ 1.0–1.3 on carpet. Traction is often the limiting factor.</td></tr><tr><td>Motor, gear ratio, stator limit</td><td>Sets the torque-speed curve and current cap.</td></tr><tr><td>Planning voltage</td><td>Plan below 12 V (11 V default) so feedback has headroom.</td></tr><tr><td>Intake</td><td>Which side it deploys from, how far it reaches past the bumper, its width (0 = the whole side) and offset. Only counts where a path has an <a href="/Mayhem/app/constraints#intake-extended">Intake extended</a> constraint.</td></tr></tbody></table><p>The panel on the right shows the derived limits (free speed, max acceleration, max angular velocity) and what limits your acceleration, for example <code>friction</code>.</p><h2 id="other-settings" tabindex="-1">Other settings <a class="header-anchor" href="#other-settings" aria-label="Permalink to &quot;Other settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What&#39;s there</th></tr></thead><tbody><tr><td><strong>Path solver</strong></td><td>Sample spacing, route candidates and the solve time limit. A larger spacing or fewer candidates makes generation faster.</td></tr><tr><td><strong>Project</strong></td><td>The deploy folder.</td></tr><tr><td><strong>Appearance</strong></td><td>Light or dark theme.</td></tr><tr><td><strong>Shortcuts</strong></td><td>Keyboard shortcuts.</td></tr><tr><td><strong>About &amp; updates</strong></td><td>Version and update check.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Match the real robot</p><p>The same mass, moment of inertia, wheel radius and max speed also drive MayhemLib&#39;s feedforward. If they don&#39;t match the real robot, the feedforward and force feedforward on the robot will be wrong. See <a href="/Mayhem/lib/tuning">Tuning the follower</a>.</p></div>',8)])])}const u=r(d,[["render",n]]);export{f as __pageData,u as default};
